#!/usr/bin/env python3
from pathlib import Path
import sys,json,zlib,base64,hashlib
if len(sys.argv)!=2: raise SystemExit("usage: patch-shishalove-1.1.78-one-shot-live-diagnostic.py <plugin-dir>")
root=Path(sys.argv[1])
payload=json.loads(zlib.decompress(base64.b64decode("")))
for rel,spec in payload.items():
 p=root/rel; data=p.read_bytes()
 if hashlib.sha256(data).hexdigest()!=spec["sha"]: raise SystemExit("unexpected Visual Recall 1.1.78 baseline: "+rel)
 lines=data.decode("utf-8").splitlines(keepends=True)
 for i1,i2,text in reversed(spec["ops"]): lines[i1:i2]=text.splitlines(keepends=True)
 p.write_text("".join(lines),encoding="utf-8")
p=(root/"shishalove-app-bridge.php").read_text()
for token in ["Version: 1.1.78","LIVE VISUAL SEARCH DIAGNOSTIC","wp_ajax_slb_visual_live_diag_178","merged_recall_candidates_before_cap","MOZE TRACE","SUSPICIOUS SCORE BREAKDOWN","slb_visual_diag_readonly_178"]:
 if token not in p: raise SystemExit("missing one-shot diagnostic token: "+token)
if "Version: 1.1.79" in p: raise SystemExit("version bump forbidden")
print("Bridge 1.1.78 one-shot live admin diagnostic applied; production ranking unchanged")
